import React from 'react';
import {
  Alert,
  Button,
  Stack,
  Typography,
} from '@mui/material';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import { Link as RouterLink } from 'react-router-dom';
import ApplicationWarningResolver from './ApplicationWarningResolver';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';

type MeteredBillRemediationStripProps = {
  ocrConfidencePct?: number | null;
  isSpendProxy?: boolean;
  period?: string;
  documentId?: string;
  onResolved?: () => void;
};

const TIER1_OCR_THRESHOLD_PCT = 75;

const MeteredBillRemediationStrip: React.FC<MeteredBillRemediationStripProps> = ({
  ocrConfidencePct,
  isSpendProxy = true,
  period = 'annual',
  documentId,
  onResolved,
}) => {
  const belowTier1Gate = ocrConfidencePct != null && ocrConfidencePct < TIER1_OCR_THRESHOLD_PCT;

  if (!isSpendProxy && !belowTier1Gate) {
    return null;
  }

  return (
    <Alert severity={belowTier1Gate ? 'error' : 'warning'} sx={{ mb: 2 }}>
      <Stack spacing={1}>
        <Typography variant="subtitle2" fontWeight={700}>
          {belowTier1Gate ? 'Bill image is hard to read' : 'Upload your bills for better accuracy'}
        </Typography>
        <Typography variant="body2">
          {belowTier1Gate
            ? 'Please re-upload a clearer PDF or photo, or type the units from the bill (kWh, litres, kL).'
            : 'Accounting imports only have ₹ amounts. Upload power, fuel, or water bills and we read the units automatically.'}
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Button
            size="small"
            variant="contained"
            component={RouterLink}
            to={DOCUMENT_UPLOAD_PATH}
            startIcon={<UploadFileIcon />}
          >
            Upload bills
          </Button>
          <ApplicationWarningResolver
            compact
            period={period}
            documentId={documentId}
            warnings={[{
              type: belowTier1Gate ? 'ocr_unreadable' : 'spend_proxy_heavy',
              message: 'Upload power, fuel, or water bills with meter readings',
            }]}
            onResolved={onResolved}
          />
        </Stack>
      </Stack>
    </Alert>
  );
};

export default MeteredBillRemediationStrip;
