import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Typography,
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  Edit as EditIcon,
  HelpOutline as HelpOutlineIcon,
  UploadFile as UploadFileIcon,
  Verified as VerifiedIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import type { Document } from '../services/documentService';
import documentService from '../services/documentService';
import ExtractedBillTransactionsPreview from './ExtractedBillTransactionsPreview';
import { DOCUMENT_UPLOAD_PATH } from '../constants/documentRoutes';
import {
  buildVerifyExtractedDataPayload,
  getExtractedDataVerificationState,
  getExtractedVerificationFields,
  getUncertaintyPrompts,
  hasOutstandingUncertainty,
  isExtractedDataVerified,
  shouldShowExtractedDataVerification,
  type ExtractedVerificationFields,
  type UncertaintyPrompt,
} from '../utils/extractedDataVerification';

export interface ExtractedDataVerificationPanelProps {
  document: Document;
  compact?: boolean;
  onVerified?: (document: Document) => void;
}

const FIELD_TO_FORM_KEY: Record<string, keyof ExtractedVerificationFields> = {
  category: 'category',
  fuelType: 'fuelType',
  electricityUnitPriceInr: 'electricityUnitPriceInr',
  waterUnitPriceInr: 'waterUnitPriceInr',
  wasteUnitCostInr: 'wasteUnitCostInr',
  fuelUnitPriceInr: 'fuelUnitPriceInr',
  activityQuantity: 'activityQuantity',
  reviewConfirmed: 'reviewConfirmed',
};

const FIELD_LABELS: Record<string, string> = {
  category: 'What is this bill for?',
  fuelType: 'Fuel type',
  electricityUnitPriceInr: 'Rate on bill (₹/kWh)',
  waterUnitPriceInr: 'Water rate (₹/L)',
  wasteUnitCostInr: 'Waste cost (₹/kg)',
  fuelUnitPriceInr: 'Fuel rate (₹/unit)',
  activityQuantity: 'Units from bill (kWh)',
  reviewConfirmed: 'I checked the details',
};

const simplifyPromptText = (prompt: UncertaintyPrompt): string => {
  const map: Record<string, string> = {
    clarify_bill_category: 'Pick the closest category for this bill.',
    clarify_fuel_type: 'Which fuel is on this bill?',
    clarify_electricity_unit_price: 'What ₹/kWh rate is printed on the bill?',
    clarify_electricity_kwh: 'If you know the kWh from the bill, enter it here (optional).',
    clarify_water_unit_price: 'What water rate is printed on the bill?',
    clarify_waste_unit_cost: 'What disposal cost per kg is on the bill?',
    clarify_fuel_unit_price: 'What fuel rate is printed on the bill?',
    clarify_review_confirmation: 'Please confirm the extracted details look correct.',
  };
  return map[prompt.id] || prompt.prompt;
};

const ExtractedDataVerificationPanel: React.FC<ExtractedDataVerificationPanelProps> = ({
  document,
  compact = false,
  onVerified,
}) => {
  const [form, setForm] = useState<ExtractedVerificationFields>(() =>
    getExtractedVerificationFields(document)
  );
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);

  const verificationState = useMemo(
    () => getExtractedDataVerificationState(document),
    [document]
  );
  const verified = isExtractedDataVerified(document);
  const prompts = useMemo(() => getUncertaintyPrompts(document), [document]);
  const needsAnswers = hasOutstandingUncertainty(document);

  useEffect(() => {
    setForm(getExtractedVerificationFields(document));
    setError(null);
    setSuccess(null);
    setWarnings([]);
  }, [document]);

  if (!shouldShowExtractedDataVerification(document)) {
    return null;
  }

  const handleChange = (field: keyof ExtractedVerificationFields, value: string | boolean) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    setError(null);
    setSuccess(null);
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    setError(null);
    setSuccess(null);
    setWarnings([]);

    try {
      const payload = buildVerifyExtractedDataPayload(form, prompts);
      const response = await documentService.verifyExtractedData(
        document.id,
        payload as Parameters<typeof documentService.verifyExtractedData>[1]
      );
      if (!response.success) {
        setError(response.message || 'Unable to verify extracted bill data');
        return;
      }

      setSuccess(response.message);
      setWarnings(response.warnings || []);
      onVerified?.(response.document);
    } catch (submitError: unknown) {
      const message = submitError instanceof Error
        ? submitError.message
        : 'Unable to verify extracted bill data';
      setError(message);
    } finally {
      setSubmitting(false);
    }
  };

  const submitLabel = verified
    ? 'Save and use for carbon'
    : 'Confirm and use for carbon';

  const answerPrompts = prompts.filter((prompt) => prompt.inputType !== 'bill_upload');
  const billUploadPrompts = prompts.filter((prompt) => prompt.inputType === 'bill_upload');

  const renderPrompt = (prompt: UncertaintyPrompt) => {
    const formKey = FIELD_TO_FORM_KEY[prompt.field];
    if (!formKey) return null;
    const helper = simplifyPromptText(prompt);

    if (prompt.inputType === 'confirm') {
      return (
        <Grid item xs={12} key={prompt.id}>
          <FormControlLabel
            control={(
              <Checkbox
                checked={Boolean(form.reviewConfirmed)}
                onChange={(event) => handleChange('reviewConfirmed', event.target.checked)}
                color="warning"
              />
            )}
            label={helper}
          />
        </Grid>
      );
    }

    const fieldLabel = FIELD_LABELS[prompt.field] || prompt.field;

    if (prompt.inputType === 'select') {
      const value = String(form[formKey] ?? '');
      return (
        <Grid item xs={12} sm={6} key={prompt.id}>
          <FormControl fullWidth size="small" required={prompt.required !== false}>
            <InputLabel id={`${prompt.id}-label`}>{fieldLabel}</InputLabel>
            <Select
              labelId={`${prompt.id}-label`}
              label={fieldLabel}
              value={value}
              onChange={(event) => handleChange(formKey, String(event.target.value))}
            >
              <MenuItem value="">
                <em>Select…</em>
              </MenuItem>
              {(prompt.options || []).map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
            {helper}
            {prompt.required === false ? ' (optional)' : ''}
          </Typography>
        </Grid>
      );
    }

    if (prompt.inputType === 'number') {
      const value = String(form[formKey] ?? '');
      return (
        <Grid item xs={12} sm={6} key={prompt.id}>
          <TextField
            fullWidth
            size="small"
            type="number"
            label={fieldLabel}
            value={value}
            onChange={(event) => handleChange(formKey, event.target.value)}
            required={prompt.required !== false}
            inputProps={{ min: 0, step: 'any' }}
            helperText={helper}
          />
        </Grid>
      );
    }

    return (
      <Grid item xs={12} sm={6} key={prompt.id}>
        <TextField
          fullWidth
          size="small"
          label={fieldLabel}
          value={String(form[formKey] ?? '')}
          onChange={(event) => handleChange(formKey, event.target.value)}
          required={prompt.required !== false}
          helperText={helper}
        />
      </Grid>
    );
  };

  return (
    <Box
      id={document.id ? `bill-verify-${document.id}` : 'bill-verify-panel'}
      sx={{
        mt: compact ? 1.5 : 2,
        p: compact ? 1.5 : 2,
        borderRadius: 1,
        border: '1px solid',
        borderColor: verified ? 'success.light' : 'warning.light',
        bgcolor: verified ? 'success.50' : 'warning.50',
      }}
    >
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1.5, flexWrap: 'wrap' }}>
        {verified ? (
          <VerifiedIcon color="success" fontSize="small" />
        ) : (
          <EditIcon color="warning" fontSize="small" />
        )}
        <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600 }}>
          Quick check of this bill
        </Typography>
        <Chip
          size="small"
          color={verified ? 'success' : 'warning'}
          label={verified ? 'Ready for carbon' : 'Needs a quick check'}
        />
        {needsAnswers && !verified && (
          <Chip
            size="small"
            color="error"
            variant="outlined"
            icon={<HelpOutlineIcon />}
            label="A few answers needed"
          />
        )}
      </Box>

      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Confirm vendor, date, and invoice number. Amounts below are for review only.
        {needsAnswers ? ' Fill any missing fields so carbon stays accurate.' : ''}
      </Typography>

      <Grid container spacing={2}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Vendor name"
            value={form.vendorName}
            onChange={(event) => handleChange('vendorName', event.target.value)}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Bill date"
            type="date"
            value={form.date}
            onChange={(event) => handleChange('date', event.target.value)}
            InputLabelProps={{ shrink: true }}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="GSTIN"
            value={form.gstin}
            onChange={(event) => handleChange('gstin', event.target.value.toUpperCase())}
            placeholder="15-character GST number"
            inputProps={{ maxLength: 15 }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Invoice number"
            value={form.invoiceNumber}
            onChange={(event) => handleChange('invoiceNumber', event.target.value)}
            required
          />
        </Grid>
      </Grid>

      {billUploadPrompts.length > 0 && (
        <Alert severity="info" icon={<UploadFileIcon fontSize="inherit" />} sx={{ mt: 2.5 }}>
          <Typography variant="body2" sx={{ mb: 1 }}>
            For best accuracy, upload a clear photo or PDF of the actual bill (power, fuel, or water).
            We read units and rates for you.
          </Typography>
          <Button
            size="small"
            variant="contained"
            component={RouterLink}
            to={DOCUMENT_UPLOAD_PATH}
            startIcon={<UploadFileIcon />}
          >
            Upload bill
          </Button>
        </Alert>
      )}

      {answerPrompts.length > 0 && (
        <Box sx={{ mt: 2.5 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
            A few quick answers
          </Typography>
          <Grid container spacing={2}>
            {answerPrompts.map((prompt) => renderPrompt(prompt))}
          </Grid>
        </Box>
      )}

      <ExtractedBillTransactionsPreview document={document} compact={compact} />

      {error && (
        <Alert severity="error" sx={{ mt: 2 }}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mt: 2 }} icon={<CheckCircleIcon fontSize="inherit" />}>
          {success}
          {verificationState.verifiedAt && verified && (
            <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
              Last verified: {new Date(verificationState.verifiedAt).toLocaleString()}
            </Typography>
          )}
        </Alert>
      )}

      {warnings.length > 0 && (
        <Alert severity="warning" sx={{ mt: 2 }}>
          {warnings.map((warning) => (
            <Typography key={warning} variant="body2">
              {warning}
            </Typography>
          ))}
        </Alert>
      )}

      <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
        <Button
          variant="contained"
          color={verified ? 'primary' : 'success'}
          onClick={() => {
            void handleSubmit();
          }}
          disabled={submitting}
          startIcon={submitting ? <CircularProgress size={16} color="inherit" /> : undefined}
        >
          {submitting ? 'Submitting…' : submitLabel}
        </Button>
      </Box>
    </Box>
  );
};

export default ExtractedDataVerificationPanel;
